+      function animate(now) {
+        const idle = now - lastMove > 1600;
+        const targetX = mouseActive && !idle ? pointer.x : 0;
+        const targetY = mouseActive && !idle ? pointer.y : 0;
+        eased.x += (targetX - eased.x) * 0.055;
+        eased.y += (targetY - eased.y) * 0.055;
+
+        draw((now - start) / 1000);
+        frameId = requestAnimationFrame(animate);
+      }
+
+      function startLoop() {
+        cancelAnimationFrame(frameId);
+        start = performance.now();
+        if (reducedMotion) {
+          eased.x = 0;
+          eased.y = 0;
+          draw(0);
+        } else {
+          frameId = requestAnimationFrame(animate);
+        }
+      }
+
+      resetParticles();
+      resize();
+      startLoop();
